1	import Link from "next/link";
2	import { Reveal } from "./Reveal";
3	import { IconArrow, IconCheck } from "./icons";
4	
5	export function SectionHeading({
6	  label,
7	  title,
8	  sub,
9	  center = true,
10	}: {
11	  label?: string;
12	  title: React.ReactNode;
13	  sub?: React.ReactNode;
14	  center?: boolean;
15	}) {
16	  return (
17	    <div className={`${center ? "mx-auto max-w-2xl text-center" : "max-w-2xl"}`}>
18	      {label && <p className="section-label mb-3">{label}</p>}
19	      <h2 className="text-3xl font-bold tracking-tight text-[var(--fg)] sm:text-4xl">{title}</h2>
20	      {sub && <p className="mt-4 text-lg leading-relaxed text-[var(--fg-muted)]">{sub}</p>}
21	    </div>
22	  );
23	}
24	
25	export function FeatureCard({
26	  icon,
27	  title,
28	  children,
29	  delay = 0,
30	}: {
31	  icon: React.ReactNode;
32	  title: string;
33	  children: React.ReactNode;
34	  delay?: number;
35	}) {
36	  return (
37	    <Reveal delay={delay} className="card card-hover group h-full">
38	      <div className="mb-4 inline-flex rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-3 text-brand-300 transition-transform duration-200 group-hover:scale-105">
39	        {icon}
40	      </div>
41	      <h3 className="text-base font-semibold text-[var(--fg)]">{title}</h3>
42	      <p className="mt-2 text-sm leading-relaxed text-[var(--fg-muted)]">{children}</p>
43	    </Reveal>
44	  );
45	}
46	
47	export function TrustBadges({ items }: { items: string[] }) {
48	  return (
49	    <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
50	      {items.map((t) => (
51	        <span key={t} className="inline-flex items-center gap-2 text-sm text-slate-400">
52	          <span className="flex h-4.5 w-4.5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
53	            <IconCheck size={12} />
54	          </span>
55	          {t}
56	        </span>
57	      ))}
58	    </div>
59	  );
60	}
61	
62	export function CtaBand() {
63	  return (
64	    <Reveal className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-850/70 px-8 py-16 text-center backdrop-blur-md sm:px-16">
65	      <div
66	        className="pointer-events-none absolute inset-0 opacity-70"
67	        style={{
68	          backgroundImage:
69	            "radial-gradient(ellipse 60% 60% at 30% 0%, rgba(59,130,246,0.18), transparent), radial-gradient(ellipse 50% 60% at 80% 100%, rgba(138,112,251,0.18), transparent)",
70	        }}
71	      />
72	      <div className="relative">
73	        <h2 className="mx-auto max-w-2xl text-3xl font-bold tracking-tight sm:text-4xl">
74	          Deploy your first server in <span className="grad-text">under a minute</span>
75	        </h2>
76	        <p className="mx-auto mt-4 max-w-xl text-lg text-slate-400">
77	          No credit card required to get started. Spin up a VPS, break things, and only pay for
78	          what you keep running.
79	        </p>
80	        <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
81	          <Link href="/register" className="btn-primary px-6 py-3 text-base">
82	            Get Started Free
83	            <IconArrow size={16} />
84	          </Link>
85	          <Link href="/pricing" className="btn-secondary px-6 py-3 text-base">
86	            Compare plans
87	          </Link>
88	        </div>
89	      </div>
90	    </Reveal>
91	  );
92	}
