181	
182	  /* ── Marketing design system (v2 redesign) ─────────────────────────────────
183	     Shared primitives so every page reads as one designed site. The Section
184	     component alternates these background "tones" to give the long pages rhythm
185	     instead of a flat stack. Colors/animations are the existing brand system. */
186	
187	  /* Eyebrow label above section/hero headings (the ubiquitous uppercase tag). */
188	  .eyebrow {
189	    @apply inline-flex items-center gap-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-brand-300;
190	  }
191	  .eyebrow-pill {
192	    @apply inline-flex items-center gap-2 rounded-full border border-brand-500/20 bg-brand-500/[0.08] px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-brand-200;
193	  }
194	
195	  /* Section background tones for alternating rhythm. "panel" is a hair lighter
196	     than the page with hairline separators; "deep" recedes. Replaces one-off
197	     inline gradients scattered across pages. */
198	  .tone-panel {
199	    @apply border-y border-white/[0.05] bg-navy-900/40;
200	  }
201	  .tone-deep {
202	    background: linear-gradient(180deg, rgb(6 10 20 / 0) 0%, rgb(8 12 24 / 0.6) 50%, rgb(6 10 20 / 0) 100%);
203	  }
204	
205	  /* Foreground tokens so tone-aware primitives (SectionTitle, FeatureCard) flip
206	     text automatically. Default = the dark theme's light text. */
207	  :root {
208	    --fg: #ffffff;
209	    --fg-muted: #94a3b8; /* slate-400 */
210	  }
211	
212	  /* "light" tone — a rare, deliberate light band to break up the dark theme and
213	     divide long pages (used sparingly, ~one per page). Flips the foreground
214	     tokens to dark and restyles surfaces/buttons inside so everything stays
215	     legible without touching each call site. */
216	  .tone-light {
217	    @apply border-y border-slate-200/70 text-slate-700;
218	    background: linear-gradient(180deg, #f4f3fb 0%, #ebe9f5 100%);
219	    --fg: #0f172a;       /* slate-900 */
220	    --fg-muted: #475569; /* slate-600 */
221	  }
222	  .tone-light .card {
223	    @apply border-slate-200 bg-white text-slate-700;
224	    box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 16px 36px -20px rgb(15 23 42 / 0.22);
225	  }
226	  .tone-light .card-hover:hover {
227	    @apply border-brand-500/40 bg-white;
228	  }
229	  .tone-light .glass {
230	    @apply border-slate-200 bg-white/70;
231	  }
232	  .tone-light .section-label {
233	    @apply text-slate-500;
234	  }
235	  .tone-light .btn-secondary {
236	    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
237	  }
238	  .tone-light .btn-ghost {
239	    @apply text-slate-600 hover:bg-slate-900/[0.06] hover:text-slate-900;
240	  }
241	
242	  /* Reusable hero aura — the dual-radial violet/blue glow that ~10 sub-page
243	     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
