3	/**
4	 * Shared "app window" chrome for the marketing showcase mock-screens — the same
5	 * visual language as the terminal/browser mocks on the vibe-coding page: a dark
6	 * navy panel, macOS traffic lights, a small title, and an optional right-hand
7	 * status pill. All showcase screens compose their body inside this frame so the
8	 * set reads as one designed system.
9	 *
10	 * Server-safe (no client JS). Motion lives inside the body via `motion-safe:`
11	 * utilities, and the whole frame is meant to be wrapped in <Reveal> at the call
12	 * site for the scroll fade-in.
13	 */
14	export function ScreenFrame({
15	  title,
16	  icon,
17	  live,
18	  liveLabel = "live",
19	  children,
20	  className = "",
21	}: {
22	  title: string;
23	  icon?: ReactNode;
24	  /** Show a pulsing green status pill in the header. */
25	  live?: boolean;
26	  liveLabel?: string;
27	  children: ReactNode;
28	  className?: string;
29	}) {
30	  return (
31	    <div
32	      className={`relative overflow-hidden rounded-2xl border border-white/10 bg-[#0a0e1a] shadow-2xl shadow-black/40 ${className}`}
33	    >
34	      {/* soft brand aura behind the panel edges */}
35	      <div
36	        className="pointer-events-none absolute -inset-10 -z-10 opacity-70"
37	        style={{
38	          backgroundImage:
39	            "radial-gradient(ellipse 50% 55% at 12% 0%, rgba(59,130,246,0.16), transparent), radial-gradient(ellipse 45% 55% at 90% 100%, rgba(138,112,251,0.18), transparent)",
40	        }}
41	        aria-hidden
42	      />
43	      <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.03] px-4 py-2.5">
44	        <span className="h-3 w-3 rounded-full bg-[#ff5f57]" />
45	        <span className="h-3 w-3 rounded-full bg-[#febc2e]" />
46	        <span className="h-3 w-3 rounded-full bg-[#28c840]" />
47	        <span className="ml-2 flex min-w-0 items-center gap-1.5 text-[11px] font-medium text-slate-400">
48	          {icon && <span className="text-slate-500">{icon}</span>}
49	          <span className="truncate">{title}</span>
50	        </span>
51	        {live && (
52	          <span className="ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
53	            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
54	            {liveLabel}
55	          </span>
56	        )}
57	      </div>
58	      <div className="relative">{children}</div>
59	    </div>
60	  );
