"use client";

import { useEffect, useRef, useState } from "react";
import { ScreenFrame } from "./Frame";
import { IconServer, IconCheck, IconCode, IconDisk, IconApps, IconArrow } from "../icons";

/**
 * The centerpiece animated "product screen" for the migration landing page.
 *
 * A single app-window mock (ScreenFrame) that loops through the real migration
 * flow so the marketing page feels alive and premium without overclaiming:
 *
 *   0. Connect your old server   — host + SSH, one "Scan" button
 *   1. Scanning…                 — read-only probes running on the source
 *   2. Here's what we found      — detected apps / containers / databases fill in
 *   3. One click → migrating     — progress bar with the real worker phase labels
 *   4. Migrated & running ✓       — green verified checks
 *
 * All copy mirrors what the wizard/worker actually do (auto-detect via read-only
 * SSH, no DB passwords, installs prerequisites, copies to the same paths, brings
 * Docker/compose + services up, verifies what's running).
 *
 * Motion is JS-driven (a small step machine, same pattern as AnimatedHero) but
 * honours prefers-reduced-motion: those users get the finished "running" state
 * rendered statically, with no loop and no intermediate motion.
 */

type Step = 0 | 1 | 2 | 3 | 4;

// Detected items — mirrors detectSource() output (signatures, size labels, DBs).
const FOUND = [
  { icon: <IconCode size={15} />, label: "WordPress site", path: "/var/www/html", size: "4.2 GB" },
  { icon: <IconApps size={15} />, label: "Next.js app", path: "/srv/billing", size: "42 MB" },
  { icon: <IconServer size={15} />, label: "3 Docker containers", path: "redis · postgres · app", size: "compose" },
  { icon: <IconDisk size={15} />, label: "MySQL + PostgreSQL", path: "all databases · no password", size: "1.6 GB" },
];

// Progress phases — the real report() labels from worker/migrate-real.ts.
const PHASES = [
  { at: 16, label: "Installing prerequisites…", detail: "Docker Engine + compose, MySQL, PostgreSQL, nginx" },
  { at: 40, label: "Copying files…", detail: "to the same paths on your new server" },
  { at: 62, label: "Migrating databases…", detail: "dumped via root on the source — no password" },
  { at: 78, label: "Starting containers…", detail: "docker compose up -d" },
  { at: 94, label: "Verifying…", detail: "docker ps shows 3 running containers" },
];

// Done state — the verified/running summary.
const RUNNING = [
  "Files restored to their original paths",
  "MySQL + PostgreSQL databases imported",
  "3 Docker containers up (compose)",
  "Ports 443, 3000, 6379 listening",
];

function phaseFor(pct: number) {
  let p = PHASES[0];
  for (const ph of PHASES) if (pct >= ph.at) p = ph;
  return p;
}

export function MigrationScreens() {
  const [step, setStep] = useState<Step>(0);
  const [revealed, setRevealed] = useState(0); // how many FOUND rows are in
  const [pct, setPct] = useState(0);
  const [reduced, setReduced] = useState(false);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    if (reduce) {
      // Rest on the finished, running state — no motion, no loop.
      setReduced(true);
      setStep(4);
      setRevealed(FOUND.length);
      setPct(100);
      return;
    }

    let cancelled = false;
    const wait = (ms: number) =>
      new Promise<void>((res) => {
        const t = setTimeout(res, ms);
        timers.current.push(t);
      });

    async function loop() {
      while (!cancelled) {
        // 0 — connect
        setStep(0);
        setRevealed(0);
        setPct(0);
        await wait(2000);
        if (cancelled) return;

        // 1 — scanning
        setStep(1);
        await wait(2100);
        if (cancelled) return;

        // 2 — found (rows fill in one by one)
        setStep(2);
        for (let i = 1; i <= FOUND.length; i++) {
          if (cancelled) return;
          setRevealed(i);
          await wait(480);
        }
        await wait(1400);
        if (cancelled) return;

        // 3 — one click → migrating (progress fills)
        setStep(3);
        setPct(0);
        for (let p = 0; p <= 100; p += 2) {
          if (cancelled) return;
          setPct(p);
          await wait(52);
        }
        await wait(500);
        if (cancelled) return;

        // 4 — migrated & running
        setStep(4);
        await wait(3400);
      }
    }

    loop();
    return () => {
      cancelled = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, []);

  const liveLabel =
    step === 0 ? "ready" : step === 1 ? "scanning" : step === 3 ? "migrating" : step === 4 ? "running" : "detected";

  return (
    <ScreenFrame
      title="Nxeon · Migration"
      icon={<IconServer size={13} />}
      live
      liveLabel={liveLabel}
      className="mx-auto w-full max-w-lg"
    >
      {/* Fixed height so the looping steps don't shift the page layout. */}
      <div className="relative min-h-[420px] p-4 sm:p-5">
        {/* Step 0 — connect ------------------------------------------------ */}
        <Pane show={step === 0}>
          <p className="text-[12px] font-medium text-slate-300">Connect your old server</p>
          <p className="mt-1 text-[11px] text-slate-500">Read-only. We never store your credentials.</p>
          <div className="mt-4 space-y-3">
            <Field label="Source host" value="203.0.113.24" mono />
            <div className="grid grid-cols-2 gap-3">
              <Field label="SSH port" value="22" mono />
              <Field label="User" value="root" mono />
            </div>
          </div>
          <div className="mt-5 flex items-center justify-center gap-2 rounded-xl border border-brand-500/30 bg-gradient-to-r from-accent-blue/20 to-brand-500/20 py-2.5 text-[12px] font-semibold text-brand-100">
            Scan my server <IconArrow size={14} />
          </div>
          <p className="mt-3 text-center text-[11px] text-slate-600">No agent to install. Nothing changes on this server.</p>
        </Pane>

        {/* Step 1 — scanning ---------------------------------------------- */}
        <Pane show={step === 1}>
          <div className="flex h-full min-h-[380px] flex-col items-center justify-center text-center">
            <span className="relative flex h-14 w-14 items-center justify-center">
              <span className="absolute inset-0 rounded-full border-2 border-brand-500/20" />
              <span className="absolute inset-0 rounded-full border-2 border-transparent border-t-brand-400 motion-safe:animate-spin" />
              <IconServer size={22} />
            </span>
            <p className="mt-5 text-[13px] font-semibold text-white">Scanning your server…</p>
            <div className="mt-4 w-full max-w-xs space-y-1.5 text-left font-mono text-[11px] text-slate-500">
              <ScanLine text="detecting apps in /var/www, /srv, /home…" delay={0} />
              <ScanLine text="docker ps · reading running containers" delay={260} />
              <ScanLine text="ss -lntp · mapping listening ports" delay={520} />
              <ScanLine text="probing MySQL / PostgreSQL data dirs" delay={780} />
            </div>
          </div>
        </Pane>

        {/* Step 2 — found -------------------------------------------------- */}
        <Pane show={step === 2}>
          <div className="flex items-center justify-between">
            <p className="text-[12px] font-medium text-slate-300">Here&apos;s what we found</p>
            <span className="rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
              {revealed}/{FOUND.length} detected
            </span>
          </div>
          <ul className="mt-3 space-y-2">
            {FOUND.map((f, i) => {
              const on = i < revealed;
              return (
                <li
                  key={f.label}
                  className={`flex items-center gap-3 rounded-xl border px-3 py-2.5 transition-all duration-300 ${
                    on
                      ? "border-white/[0.08] bg-white/[0.03] opacity-100"
                      : "translate-y-1 border-white/[0.04] bg-white/[0.01] opacity-30"
                  }`}
                >
                  <span
                    className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-lg transition-colors ${
                      on ? "bg-emerald-500/15 text-emerald-300" : "bg-white/[0.04] text-slate-600"
                    }`}
                  >
                    {on ? <IconCheck size={15} /> : f.icon}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-[12px] font-medium text-slate-200">{f.label}</span>
                    <span className="block truncate font-mono text-[10px] text-slate-500">{f.path}</span>
                  </span>
                  <span className="shrink-0 rounded-md bg-white/[0.05] px-1.5 py-0.5 font-mono text-[10px] text-slate-400">
                    {f.size}
                  </span>
                </li>
              );
            })}
          </ul>
          <div className="mt-4 flex items-center justify-center gap-2 rounded-xl border border-brand-500/30 bg-gradient-to-r from-accent-blue/25 to-brand-500/25 py-2.5 text-[12px] font-semibold text-white">
            Migrate everything <IconArrow size={14} />
          </div>
        </Pane>

        {/* Step 3 — migrating --------------------------------------------- */}
        <Pane show={step === 3}>
          <div className="flex h-full min-h-[380px] flex-col justify-center">
            <p className="text-[12px] font-medium text-slate-300">Migrating to nxeon-sg-01</p>
            <p className="mt-1 font-mono text-[11px] text-brand-200">{phaseFor(pct).label}</p>
            <p className="mt-0.5 font-mono text-[10px] text-slate-500">{phaseFor(pct).detail}</p>

            <div className="mt-4 h-2.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
              <div
                className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-[width] duration-100 ease-linear"
                style={{ width: `${pct}%` }}
              />
            </div>
            <p className="mt-1.5 text-right font-mono text-[10px] text-slate-500">{pct}%</p>

            <ul className="mt-4 space-y-1.5">
              {PHASES.map((ph) => {
                const done = pct > ph.at + 4;
                const active = !done && pct >= ph.at - 8;
                return (
                  <li key={ph.label} className="flex items-center gap-2.5 text-[11px]">
                    <span
                      className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-full ${
                        done
                          ? "bg-emerald-500/15 text-emerald-300"
                          : active
                            ? "bg-brand-500/20 text-brand-200"
                            : "border border-white/10 text-transparent"
                      }`}
                    >
                      {done ? (
                        <IconCheck size={10} />
                      ) : active ? (
                        <span className="h-1.5 w-1.5 rounded-full bg-brand-300 motion-safe:animate-pulse-dot" />
                      ) : null}
                    </span>
                    <span className={done ? "text-slate-400" : active ? "text-slate-200" : "text-slate-600"}>
                      {ph.label}
                    </span>
                  </li>
                );
              })}
            </ul>
          </div>
        </Pane>

        {/* Step 4 — running ------------------------------------------------ */}
        <Pane show={step === 4}>
          <div className="flex h-full min-h-[380px] flex-col justify-center">
            <div className="flex flex-col items-center text-center">
              <span className="flex h-14 w-14 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300 ring-1 ring-emerald-500/30">
                <IconCheck size={26} />
              </span>
              <p className="mt-4 text-base font-semibold text-white">Migrated &amp; running</p>
              <p className="mt-1 text-[11px] text-slate-500">on nxeon-sg-01 · verified live</p>
            </div>
            <ul className="mt-5 space-y-2">
              {RUNNING.map((r) => (
                <li key={r} className="flex items-center gap-2.5 rounded-lg bg-emerald-500/[0.06] px-3 py-2 text-[12px] text-slate-200">
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-300">
                    <IconCheck size={12} />
                  </span>
                  {r}
                </li>
              ))}
            </ul>
            <p className="mt-4 text-center text-[10px] leading-relaxed text-slate-600">
              {reduced
                ? "Anything that needs a manual touch is listed for you — we tell you exactly what."
                : "We start everything we can and flag anything that needs a manual touch."}
            </p>
          </div>
        </Pane>

        {/* Step dots (hidden for reduced motion — there's only one state). */}
        {!reduced && (
          <div className="pointer-events-none absolute bottom-3 left-1/2 flex -translate-x-1/2 gap-1.5">
            {[0, 1, 2, 3, 4].map((s) => (
              <span
                key={s}
                className={`h-1 rounded-full transition-all duration-300 ${
                  s === step ? "w-4 bg-brand-400" : "w-1 bg-white/15"
                }`}
              />
            ))}
          </div>
        )}
      </div>
    </ScreenFrame>
  );
}

/** A cross-fading absolute pane so steps swap in place without layout shift. */
function Pane({ show, children }: { show: boolean; children: React.ReactNode }) {
  return (
    <div
      className={`absolute inset-0 p-4 transition-opacity duration-500 sm:p-5 ${
        show ? "z-10 opacity-100" : "pointer-events-none opacity-0"
      }`}
      aria-hidden={!show}
    >
      {children}
    </div>
  );
}

function Field({ label, value, mono }: { label: string; value: string; mono?: boolean }) {
  return (
    <div className="rounded-xl border border-white/[0.07] bg-white/[0.02] px-3 py-2">
      <span className="block text-[9px] font-semibold uppercase tracking-wide text-slate-500">{label}</span>
      <span className={`mt-0.5 block text-[12px] text-slate-200 ${mono ? "font-mono" : ""}`}>{value}</span>
    </div>
  );
}

function ScanLine({ text, delay }: { text: string; delay: number }) {
  return (
    <p className="flex items-center gap-2 motion-safe:animate-line-in" style={{ animationDelay: `${delay}ms` }}>
      <span className="text-emerald-400">›</span>
      {text}
    </p>
  );
}

